#!/usr/bin/env bash
# 05-l7-authz.sh: Policy 3, an L7 AuthorizationPolicy on the waypoint.
# Generated by Flightbay's "Allow or deny requests" task.
#
# targetRefs the ratings Service, so the waypoint's Envoy enforces it. reviews
# may GET; reviews' POST and everything from demo-client come back 403.
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=lib.sh
source "$SCRIPT_DIR/lib.sh"

require kubectl

step "Policy 3: AuthorizationPolicy ratings-access-rule, reviews may GET (YAML from Flightbay)"
show kc apply -f "$LAB_ROOT/yaml/20-policies/40-l7-authz-ratings.yaml"
wait_code 403 "$NS_APP" demo-client GET

step "Probe"
"$SCRIPT_DIR/probe.sh" --no-jwt
log "reviews-v2 GET 200. reviews-v2 POST 403 and demo-client GET 403 are HTTP responses from"
log "the waypoint, not resets: the connection was fine, the request was not."

step "Bookinfo still works"
show kc -n "$NS_APP" exec deploy/demo-client -- curl -s -o /dev/null -w '%{http_code}\n' http://productpage:9080/productpage
log "productpage calls reviews, and reviews-v2 GETs ratings, which the rule allows."

echo
ok "Policy 3 in place: identity AND method, decided per request in the waypoint."
log "Next: ./scripts/06-jwt.sh"
